{"packet_id":"D007-01","doc_id":"D007","jurisdiction":"CA","category":"security_deposits","lifecycle":"enacted","title":"California security deposit cap (AB 12)","requirement":"A landlord may charge no more than one month's rent as a security deposit; certain small owners may charge up to two months. Deposits must be returned within 21 days with an itemized statement.","key_value":"1 month's rent (2 months for small owners)","coverage_conditions":"All residential rental tenancies in California.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":4,"owner_dependent":true,"other":"Two-month cap for small owners: at most 2 rental properties with 4 or fewer residential units total"},"exemptions":"Landlords who own only two rental properties with no more than four residential units total, if ownership is a natural person, family trust, or LLC of natural persons, may charge up to two months' rent.","penalty":null,"effective_date":"2024-07-01","citation":"AB 12","quoted_span":"Starting July 1, 2024, many landlords may only charge one month's rent for unfurnished and furnished units","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D007-01","doc_id":"D007","jurisdiction":"Berkeley, CA","category":"security_deposits","lifecycle":"enacted","title":"Berkeley Rent Ordinance security deposit interest","requirement":"For units covered by the Berkeley Rent Ordinance, a landlord must pay the tenant interest on the security deposit at the end of each year, and a prorated amount if the tenant moves out before the end of the year.","key_value":null,"coverage_conditions":"Tenancies in units fully or partially covered by Berkeley's Rent Ordinance.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Berkeley Mun. Code ch. 13.76","quoted_span":"For tenancies in units fully or partially covered by Berkeley's Rent Ordinance, landlords must pay tenants interest on their security deposit at the end of each year and a prorated amount if the tenant moves out before the end of the year.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
